mapper.select:
SELECT id, filename, status, total_items, parsed_items, confidence, created_at
FROM curriculum_import_job
WHERE deleted = 0
ORDER BY ${sortColumn} ${sortDir}
LIMIT #{offset}, #{size}

mapper.update:
UPDATE curriculum_import_job
SET status = #{status}, updated_at = NOW()
WHERE id = #{id}

mapper.select:
SELECT id, job_id, course_code, course_name, semester, credits, hours, category, module,
       prerequisites_json, ability_tags_json, confidence, page_ref, status
FROM curriculum_import_item
WHERE job_id = #{jobId}

    AND status = #{status}

ORDER BY ${sortColumn} ${sortDir}
LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM curriculum_import_item
WHERE job_id = #{jobId}

    AND status = #{status}

mapper.update:
UPDATE curriculum_import_item
SET ability_tags_json = #{abilityTagsJson}, updated_at = NOW()
WHERE id = #{id}

UPDATE curriculum_import_item
SET status = #{status}, updated_at = NOW()
WHERE id = #{id}

mapper.select:
SELECT id, name, major, course_count, status, published_at, published_by
FROM curriculum_version
WHERE deleted = 0
ORDER BY ${sortColumn} ${sortDir}
LIMIT #{offset}, #{size}
